const body = $input.first().json.body || $input.first().json;
const project_id = (body.project_id || '').trim();
if (!project_id) throw new Error('project_id is required');
return [{ json: { project_id } }];

// Extract client_code from project record to fetch the brief
const project = $input.first().json;
const client_code = project.client_code || (project.fields && project.fields.client_code) || '';
const project_id = $('Extract Project ID').first().json.project_id;
if (!client_code) throw new Error('No client_code found in project record');
return [{ json: { client_code, project_id, project } }];

// ============================================================
// Merge all data sources and build the Writer Prompt
// Only includes approved concepts (NOT all concepts)
// ============================================================

const projectData = $('Extract Client Code').first().json;
const project_id = projectData.project_id;
const project = projectData.project;

// Get approved concepts
const approvedConcepts = $('Fetch Approved Concepts').all().map(item => {
  const d = item.json;
  return {
    id: d.id,
    concept_name: d.concept_name || d.fields?.concept_name || 'Unnamed',
    framework: d.framework || d.fields?.framework || 'PAS',
    hook_type: d.hook_type || d.fields?.hook_type || 'curiosity-gap',
    hook_text: d.hook_text || d.fields?.hook_text || '',
    format: d.format || d.fields?.format || 'Talking Head',
    funnel_stage: d.funnel_stage || d.fields?.funnel_stage || 'TOF',
    virality_score: d.virality_score || d.fields?.virality_score || 5,
    concept_pitch: d.concept_pitch || d.fields?.concept_pitch || '',
    emotional_journey: d.emotional_journey || d.fields?.emotional_journey || '',
    target_objection: d.target_objection || d.fields?.target_objection || '',
    platform: d.platform || d.fields?.platform || 'TikTok'
  };
});

// Get research data
const researchRecords = $('Fetch Research Data').all().map(item => {
  const d = item.json;
  return {
    type: d.research_type || d.fields?.research_type || '',
    category: d.category || d.fields?.category || '',
    content: d.content || d.fields?.content || '',
    source: d.source || d.fields?.source || ''
  };
});

// Get reference videos
const refRecords = $('Fetch Reference Videos').all().map(item => {
  const d = item.json;
  return {
    url: d.url || d.fields?.url || '',
    platform: d.platform || d.fields?.platform || '',
    format: d.format || d.fields?.format || '',
    hook: d.hook || d.fields?.hook || '',
    why_it_works: d.why_it_works || d.fields?.why_it_works || '',
    adaptation_idea: d.adaptation_idea || d.fields?.adaptation_idea || ''
  };
});

// Build brief from Google Sheets
let brief = {};
try {
  const row = $('Fetch Client Brief').first().json;
  function c(v) { return v === undefined || v === null ? '' : String(v).trim(); }
  brief = {
    client_code: c(row.client_code),
    brand_name: c(row.brand_name),
    client_name: c(row.client_name),
    client_email: c(row.client_email),
    product_feature: c(row.product_feature),
    differentiator: c(row.differentiator),
    target_user: c(row.target_user),
    biggest_problem: c(row.biggest_problem),
    main_hesitation: c(row.main_hesitation),
    selling_proposition: c(row.selling_proposition),
    brand_personality: c(row.brand_personality),
    credibility_point: c(row.credibility_point),
    transformation: c(row.transformation),
    social_proof: c(row.social_proof),
    compliance: c(row.compliance),
    do_not_say: c(row.do_not_say),
    additional_notes: c(row.additional_notes),
    num_scripts: parseInt(c(row.num_scripts)) || 3
  };
} catch(e) {
  // Use project data as fallback
  brief = {
    brand_name: project.brand_name || project.fields?.brand_name || 'Brand',
    client_code: project.client_code || project.fields?.client_code || '',
    client_name: project.client_name || project.fields?.client_name || '',
    num_scripts: project.num_scripts || project.fields?.num_scripts || 3
  };
}

// Build research summary text
const researchSummary = researchRecords.map(r => 
  `[${r.type}] (${r.source} | ${r.category}): ${r.content}`
).join('\n');

// Build reference summary text
const refSummary = refRecords.map(r =>
  `- ${r.platform} (${r.format}): ${r.url}\n  Hook: ${r.hook}\n  Why: ${r.why_it_works}\n  Adaptation: ${r.adaptation_idea}`
).join('\n\n');

// Build concept deck
const conceptDeck = approvedConcepts.map((c, i) =>
  `CONCEPT ${i + 1}: ${c.concept_name}\n  Framework: ${c.framework} | Hook Type: ${c.hook_type} | Format: ${c.format}\n  Funnel: ${c.funnel_stage} | Platform: ${c.platform} | Virality: ${c.virality_score}/10\n  Hook: "${c.hook_text}"\n  Pitch: ${c.concept_pitch}\n  Emotional Journey: ${c.emotional_journey}\n  Target Objection: ${c.target_objection}`
).join('\n\n');

const numConcepts = approvedConcepts.length;

const prompt = `Write COMPLETE UGC scripts for the ${numConcepts} CLIENT-APPROVED concepts below.

These concepts have been reviewed and approved by the PM and the client. Write full scripts for ALL of them.

== CLIENT BRIEF ==
Brand: ${brief.brand_name}
Product: ${brief.product_feature || 'N/A'}
Differentiator: ${brief.differentiator || 'N/A'}
Selling Proposition: ${brief.selling_proposition || 'N/A'}
Target: ${brief.target_user || 'N/A'}
Problem: ${brief.biggest_problem || 'N/A'}
Hesitation: ${brief.main_hesitation || 'N/A'}
Transformation: ${brief.transformation || 'N/A'}
Personality: ${brief.brand_personality || 'N/A'}
Credibility: ${brief.credibility_point || 'N/A'}
Social Proof: ${brief.social_proof || 'N/A'}
Compliance: ${brief.compliance || 'None'}
Do NOT Say: ${brief.do_not_say || 'None'}
Notes: ${brief.additional_notes || 'None'}

== RESEARCH INSIGHTS ==
${researchSummary || 'Research data available in Airtable.'}

== REFERENCE VIDEOS/ADS ==
${refSummary || 'Reference videos available in Airtable.'}

== APPROVED CONCEPT DECK ==
${conceptDeck}

== OUTPUT FORMAT ==
For EACH concept (all ${numConcepts}), output this JSON structure:
{
  "scripts": [
    {
      "script_number": 1,
      "concept_name": "from concept deck above",
      "concept_id": "will be matched later",
      "framework_used": "PAS / BAB / AIDA / etc.",
      "hook_type": "controversy / POV / calling-out / etc.",
      "funnel_stage": "TOF / MOF / BOF",
      "format": "the UGC format",
      "platform": "TikTok / Reels / Facebook",
      "hook": "Exact opening words (0-3 sec)",
      "hook_reinforcement": "Second line that keeps them watching (3-5 sec)",
      "problem": "Relate to viewer (5-10 sec)",
      "solution": "Natural product discovery (10-18 sec)",
      "proof": "Specific proof points (18-25 sec)",
      "cta": "Curiosity-driven close (25-30 sec)",
      "full_script": "The COMPLETE script as the creator would say it",
      "visual_direction": "Second-by-second direction",
      "on_screen_text": ["Text overlay 1", "Text overlay 2", "Text overlay 3"],
      "creator_notes": "Tone, energy, pacing, setting",
      "estimated_duration": "25 sec",
      "thumbnail_frame": "Description of first frame"
    }
  ]
}

CRITICAL: The 'full_script' must sound like a REAL PERSON. Include filler words, reactions, pauses.

Output ONLY valid JSON.`;

return [{ json: {
  prompt,
  brief,
  project_id,
  approved_concepts: approvedConcepts,
  concept_count: numConcepts,
  revision_count: 0
} }];

// ============================================================
// Build QA Agent prompt
// ============================================================

const writerOutput = $input.first().json.output || $input.first().json.text || JSON.stringify($input.first().json);
const promptData = $('Build Writer Prompt').first().json;
const brief = promptData.brief;
const revisionCount = promptData.revision_count || 0;

const prompt = `REVIEW THESE UGC SCRIPTS. You are the final quality gate.

== COMPLIANCE RULES (NON-NEGOTIABLE) ==
Compliance Policy: ${brief.compliance || 'No specific compliance rules'}
Do NOT Say: ${brief.do_not_say || 'No restrictions'}

== BRAND CONTEXT ==
Brand: ${brief.brand_name}
Product: ${brief.product_feature || 'N/A'}
Target: ${brief.target_user || 'N/A'}
Personality: ${brief.brand_personality || 'N/A'}

== SCRIPTS TO REVIEW ==
${writerOutput}

== YOUR REVIEW CHECKLIST ==
1. COMPLIANCE: Any 'do not say' violations? Unsubstantiated claims?
2. FRAMEWORK EXECUTION: Is each framework executed correctly?
3. HOOK QUALITY: Would a real person stop scrolling? Score 1-10.
4. AUTHENTICITY: Sounds like a real person or like ChatGPT?
5. AD PACING: Product reveal between 8-18 seconds?
6. PROOF SPECIFICITY: Numbers, timeframes, names — or vague?
7. CTA: Creates curiosity or is generic?
8. DIVERSITY: Different frameworks, hooks, voices across scripts?

Output this JSON:
{
  "verdict": "APPROVED" or "NEEDS_REVISION",
  "overall_quality": 7.5,
  "revision_number": ${revisionCount},
  "script_reviews": [
    {
      "script_number": 1,
      "compliance_pass": true,
      "quality_score": 8,
      "issues": [],
      "revision_notes": ""
    }
  ],
  "batch_notes": "Overall assessment"
}

Revision #${revisionCount} of max 2. ${revisionCount >= 2 ? 'FINAL REVIEW — approve with notes if quality is acceptable.' : ''}
Output ONLY valid JSON.`;

return [{ json: { prompt, brief, writer_output: writerOutput, revision_count: revisionCount, project_id: promptData.project_id, approved_concepts: promptData.approved_concepts } }];

const input = JSON.parse($input.first().json.query || '{}');
const text = (input.script_text || '').toLowerCase();
const forbidden = (input.forbidden_phrases || '').split(',').map(p => p.trim().toLowerCase()).filter(Boolean);
const violations = forbidden.filter(phrase => text.includes(phrase));
return JSON.stringify({ violations, has_violations: violations.length > 0, checked_phrases: forbidden.length });

// ============================================================
// Check QA Verdict — decision point
// ============================================================

const qaOutput = $input.first().json.output || $input.first().json.text || JSON.stringify($input.first().json);
const prevData = $('Build QA Prompt').first().json;
const writerOutput = prevData.writer_output;
let revisionCount = prevData.revision_count || 0;

let qaResult;
try {
  qaResult = JSON.parse(qaOutput);
} catch(e) {
  const match = qaOutput.match(/\{[\s\S]*\}/);
  if (match) {
    try { qaResult = JSON.parse(match[0]); } catch(e2) {
      qaResult = { verdict: 'APPROVED', batch_notes: 'Could not parse QA response, approving by default.' };
    }
  } else {
    qaResult = { verdict: 'APPROVED', batch_notes: 'Could not parse QA response, approving by default.' };
  }
}

const verdict = (qaResult.verdict || 'APPROVED').toUpperCase();
const needsRevision = verdict === 'NEEDS_REVISION' && revisionCount < 2;

return [{
  json: {
    verdict,
    needs_revision: needsRevision,
    revision_count: revisionCount + (needsRevision ? 1 : 0),
    revision_notes: qaResult.batch_notes || '',
    script_reviews: qaResult.script_reviews || [],
    overall_quality: qaResult.overall_quality || 0,
    writer_output: writerOutput,
    qa_output: qaOutput,
    project_id: prevData.project_id,
    brief: prevData.brief,
    approved_concepts: prevData.approved_concepts
  }
}];

// ============================================================
// Route back to Script Writer with revision context
// ============================================================

const verdict = $input.first().json;
const brief = verdict.brief;

const revisionFeedback = (verdict.script_reviews || []).map(r =>
  `Script ${r.script_number}: Score ${r.quality_score}/10${r.issues && r.issues.length ? ' — Issues: ' + r.issues.join(', ') : ''}${r.revision_notes ? ' — Notes: ' + r.revision_notes : ''}`
).join('\n');

const prompt = `REVISION REQUESTED — The QA agent has reviewed your scripts and sent them back.

== QA REVISION NOTES ==
${verdict.revision_notes}

== SCRIPT-LEVEL FEEDBACK ==
${revisionFeedback}

== ORIGINAL BRIEF ==
Brand: ${brief.brand_name} | Product: ${brief.product_feature || 'N/A'}
Differentiator: ${brief.differentiator || 'N/A'} | Target: ${brief.target_user || 'N/A'}
Personality: ${brief.brand_personality || 'N/A'}
Compliance: ${brief.compliance || 'None'} | Do NOT Say: ${brief.do_not_say || 'None'}

Rewrite the scripts addressing ALL revision notes. Keep what worked. Fix what didn't.
Maintain the same JSON output format as before.`;

return [{ json: {
  prompt,
  brief,
  project_id: verdict.project_id,
  approved_concepts: verdict.approved_concepts,
  concept_count: (verdict.approved_concepts || []).length,
  revision_count: verdict.revision_count
} }];

// ============================================================
// Parse approved scripts and store in Airtable
// Match scripts to concept IDs for linking
// ============================================================

const verdictData = $input.first().json;
const writerOutput = verdictData.writer_output || '';
const project_id = verdictData.project_id;
const brief = verdictData.brief;
const qaQuality = verdictData.overall_quality || 'N/A';
const approvedConcepts = verdictData.approved_concepts || [];

// Parse scripts from writer output
let scripts = [];
try {
  const parsed = JSON.parse(writerOutput);
  scripts = parsed.scripts || [parsed];
} catch(e) {
  const match = writerOutput.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      const parsed = JSON.parse(match[0]);
      scripts = parsed.scripts || [parsed];
    } catch(e2) {
      scripts = [{ script_number: 1, full_script: writerOutput, concept_name: 'Script', format: 'UGC', hook: '', visual_direction: '', on_screen_text: [], creator_notes: '', estimated_duration: '30 sec' }];
    }
  }
}

// Match scripts to concepts by name or index
const scriptRecords = scripts.map((s, i) => {
  const conceptName = s.concept_name || '';
  const matchedConcept = approvedConcepts.find(c => c.concept_name === conceptName) || approvedConcepts[i] || {};

  return {
    project_id: project_id,
    concept_id: matchedConcept.id || '',
    script_number: s.script_number || (i + 1),
    hook: s.hook || '',
    hook_reinforcement: s.hook_reinforcement || '',
    problem: s.problem || '',
    solution: s.solution || '',
    proof: s.proof || '',
    cta: s.cta || '',
    full_script: s.full_script || '',
    visual_direction: s.visual_direction || '',
    on_screen_text: Array.isArray(s.on_screen_text) ? s.on_screen_text.join(' | ') : (s.on_screen_text || ''),
    creator_notes: s.creator_notes || '',
    estimated_duration: s.estimated_duration || '30 sec',
    thumbnail_frame: s.thumbnail_frame || '',
    qa_score: qaQuality,
    pm_status: 'Pending',
    pm_notes: '',
    client_status: 'Pending',
    client_notes: '',
    overall_status: 'PM Review',
    version: 1,
    concept_name: s.concept_name || matchedConcept.concept_name || 'Concept ' + (i + 1),
    format: s.format || matchedConcept.format || 'UGC'
  };
});

return [{ json: {
  project_id,
  brief,
  script_records: scriptRecords,
  script_count: scriptRecords.length,
  qa_quality: qaQuality,
  revisions_used: verdictData.revision_count || 0
} }];

// Split script records into individual items
const data = $input.first().json;
const items = data.script_records.map(record => ({ json: record }));
return items;

// ============================================================
// Build Slack notification for PM script review
// ============================================================
const data = $('Parse Scripts for Airtable').first().json;
const brief = data.brief;
const scripts = data.script_records;
const project_id = data.project_id;

const scriptSummary = scripts.map((s, i) =>
  `${i + 1}. *${s.concept_name}* (${s.format})\n   Hook: _"${(s.hook || '').substring(0, 60)}..."_\n   Duration: ${s.estimated_duration} | QA: ${s.qa_score}/10`
).join('\n\n');

const slackBlocks = [
  {
    "type": "header",
    "text": { "type": "plain_text", "text": `Scripts Ready for PM Review: ${brief.brand_name || 'Brand'}` }
  },
  {
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": `*${scripts.length} scripts written and QA'd for ${brief.client_code || 'project'}*\nQA Score: ${data.qa_quality}/10 | Revisions used: ${data.revisions_used}\n\n${scriptSummary}`
    }
  },
  {
    "type": "divider"
  },
  {
    "type": "actions",
    "elements": [
      {
        "type": "button",
        "text": { "type": "plain_text", "text": "Review Scripts in Airtable" },
        "style": "primary",
        "url": `https://airtable.com/appvFxwZc9yU8o8pK/Scripts?filter_project_id=${project_id}`
      },
      {
        "type": "button",
        "text": { "type": "plain_text", "text": "Approve All & Deliver" },
        "url": `http://n8n-jeet.duckdns.org:5678/webhook/ugc-delivery?project_id=${project_id}&action=approve`
      }
    ]
  }
];

return [{ json: {
  project_id,
  brief,
  script_count: scripts.length,
  slack_blocks: JSON.stringify(slackBlocks),
  slack_text: `${scripts.length} UGC scripts ready for PM review: ${brief.brand_name || 'Brand'} (${brief.client_code || ''}) — QA: ${data.qa_quality}/10`
} }];

const err = $input.first().json;
let project_id = 'N/A';
try { project_id = $('Extract Project ID').first().json.project_id; } catch(e) {}
return [{ json: { project_id, error_message: err.error?.message || err.message || 'Unknown', error_node: err.error?.node?.name || 'Unknown', timestamp: new Date().toISOString() } }];
